package com.vaibhav.ediflow.ingestion.service;
import com.vaibhav.ediflow.events.*;import com.vaibhav.ediflow.ingestion.parser.*;import com.vaibhav.ediflow.ingestion.producer.EdiPublisher;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.Test;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class IngestionServiceTest {
 @Test void parseFailureIsPublishedToDlq(){X12Parser parser=mock(X12Parser.class);EdiPublisher publisher=mock(EdiPublisher.class);var metrics=new SimpleMeterRegistry();when(parser.parse(any())).thenThrow(new EdiParseException("bad envelope"));var service=new IngestionService(parser,publisher,metrics);byte[] raw="bad edi".getBytes(StandardCharsets.UTF_8);assertThrows(EdiParseException.class,()->service.ingest(raw));verify(publisher).deadLetter("bad edi","bad envelope");assertEquals(1,metrics.counter("ediflow.parse.errors").count());}
 @Test void authenticatedGatewayPartnerOverridesPayloadSender(){X12Parser parser=mock(X12Parser.class);EdiPublisher publisher=mock(EdiPublisher.class);var parsed=new CanonicalEdiEvent(UUID.randomUUID(),UUID.randomUUID(),"SPOOFED",DocumentType.PO_850,"1","1","1",Instant.now(),null);when(parser.parse(any())).thenReturn(parsed);new IngestionService(parser,publisher,new SimpleMeterRegistry()).ingest("edi".getBytes(StandardCharsets.UTF_8),"SENDERID");verify(publisher).publish(argThat(event->event.partnerCode().equals("SENDERID")&&!event.partnerId().equals(parsed.partnerId())));}
}
